# name: multiple_of_3_set_contrast
# description: Among multi-example sets whose examples are all multiples of 3 (not all sharing a last digit), yes-rate for non-example targets that are multiples of 3 minus yes-rate for non-example targets that are not; observed above model means people generalise "multiples of 3" more sharply than the model's uniform-within-family multiples prior allows, below means less sharply.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    keep = []
    exsets = {}
    for s in sets.unique():
        ex = [int(x) for x in s.split(",")]
        if len(ex) >= 2 and all(e % 3 == 0 for e in ex) and len(set(e % 10 for e in ex)) > 1:
            keep.append(s)
            exsets[s] = set(ex)
    if not keep:
        return 0.0
    sub = df[sets.isin(keep).to_numpy()]
    t = sub["target"].astype(int).to_numpy()
    ss = sub["number_set"].astype(str).to_numpy()
    inset = np.array([x in exsets[s] for s, x in zip(ss, t)])
    r = sub["rating"].to_numpy(dtype=float)
    m3 = (t % 3 == 0) & ~inset
    n3 = (t % 3 != 0) & ~inset
    if m3.sum() == 0 or n3.sum() == 0:
        return 0.0
    return float(r[m3].mean() - r[n3].mean())

# name: power_of_two_target_yes_rate
# description: Among sets whose examples are all powers of 2, the yes-rate for non-example targets that are themselves powers of 2 (e.g. 32 after "8,16", 8 after "64,4"); observed below model means people endorse the powers-of-2 concept less (the model's powers family prior / size principle is too strong), above means more.
def test_statistic(df):
    pw = {2, 4, 8, 16, 32, 64}
    sets = df["number_set"].astype(str)
    keep, exsets = [], {}
    for s in sets.unique():
        ex = [int(x) for x in s.split(",")]
        if all(e in pw for e in ex):
            keep.append(s)
            exsets[s] = set(ex)
    if not keep:
        return 0.0
    sub = df[sets.isin(keep).to_numpy()]
    t = sub["target"].astype(int).to_numpy()
    ss = sub["number_set"].astype(str).to_numpy()
    inset = np.array([x in exsets[s] for s, x in zip(ss, t)])
    r = sub["rating"].to_numpy(dtype=float)
    sel = np.isin(t, list(pw)) & ~inset
    if sel.sum() == 0:
        return 0.0
    return float(r[sel].mean())

# name: shared_contained_digit_contrast
# description: Among multi-example sets whose examples all contain some common digit d but do NOT all end in the same digit, yes-rate for non-example targets containing d minus yes-rate for non-example targets not containing d; observed above model means people generalise "contains digit d" more than the model's (family-weighted) contained-digit rules allow, observed below means less.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    uniq = sets.unique()
    info = {}
    for s in uniq:
        ex = [int(x) for x in s.split(",")]
        if len(ex) < 2 or len(set(e % 10 for e in ex)) == 1:
            continue
        common = set("0123456789")
        for e in ex:
            common &= set(str(e))
        if common:
            info[s] = (set(ex), sorted(common))
    if not info:
        return 0.0
    m = sets.isin(list(info.keys())).to_numpy()
    sub = df[m]
    tstr = sub["target"].astype(int).astype(str).to_numpy()
    tint = sub["target"].astype(int).to_numpy()
    ss = sub["number_set"].astype(str).to_numpy()
    has = np.array([any(d in t for d in info[s][1]) for s, t in zip(ss, tstr)])
    inset = np.array([t in info[s][0] for s, t in zip(ss, tint)])
    r = sub["rating"].to_numpy(dtype=float)
    a = r[has & ~inset]
    b = r[~has & ~inset]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())

# name: cell_response_disagreement
# description: Mean over (set, target) cells (each answered by several participants) of the within-cell response variance p(1-p); observed below the model mean means people agree with each other more (respond more deterministically) than the model's graded yes-probabilities imply, observed above means more disagreement than the model's probabilities imply.
def test_statistic(df):
    g = df.groupby(["number_set", "target"])["rating"].agg(["mean", "size"])
    g = g[g["size"] >= 2]
    if len(g) == 0:
        return 0.0
    p = g["mean"].to_numpy(dtype=float)
    return float(np.mean(p * (1 - p)))

# name: prime_set_contrast
# description: Among multi-example sets whose examples are all prime, yes-rate for non-example odd prime targets minus yes-rate for non-example odd composite targets; observed above model means people generalise the primes concept more sharply than the model's family-weighted prime prior predicts, below means they treat primes like generic odd numbers more.
def test_statistic(df):
    primes = {n for n in range(2, 101) if all(n % a for a in range(2, int(n ** 0.5) + 1))}
    sets = df["number_set"].astype(str)
    keep, exsets = [], {}
    for s in sets.unique():
        ex = [int(x) for x in s.split(",")]
        if len(ex) >= 2 and all(e in primes for e in ex):
            keep.append(s)
            exsets[s] = set(ex)
    if not keep:
        return 0.0
    sub = df[sets.isin(keep).to_numpy()]
    t = sub["target"].astype(int).to_numpy()
    ss = sub["number_set"].astype(str).to_numpy()
    inset = np.array([x in exsets[s] for s, x in zip(ss, t)])
    r = sub["rating"].to_numpy(dtype=float)
    isp = np.isin(t, list(primes))
    odd = t % 2 == 1
    a = r[isp & odd & ~inset]
    b = r[~isp & odd & (t > 1) & ~inset]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())
